        "`'cpu'` forces CPU regardless of available accelerators."),
    verbosity: z
        .number()
        .int()
        .optional()
        .describe('Native log verbosity forwarded to the addon (0=ERROR, 1=WARN, 2=INFO, 3=DEBUG).')
});
