export function formatArg(arg) {
    // Primitives
    if (arg === null ||
        arg === undefined ||
        typeof arg === 'string' ||
        typeof arg === 'number' ||
        typeof arg === 'boolean' ||
        typeof arg === 'symbol') {
        return String(arg);
    }
    // Functions - avoid printing source code
    if (typeof arg === 'function') {
        return '[function]';
